<?php
$beRoot=base_url('store/'.$settings->store_slug);$beCat='';foreach(($categories ?? []) as $c)if((int)$c->id===(int)($category_id ?? 0))$beCat=$c->category_name;
$beUrl=function($changes=[])use($beRoot,$search,$category_id){$q=array_filter(array_merge(['search'=>$search ?? '','category'=>$category_id ?? 0],$changes),function($v){return $v!==''&&$v!==0;});return $beRoot.'/products'.($q?'?'.http_build_query($q):'');};
?>
<main class="be-commerce be-catalogue be-shell">
 <nav class="be-crumbs" aria-label="Breadcrumb"><a href="<?= $beRoot; ?>">Home</a><span>/</span><span><?= $beCopy('shop_label'); ?></span><?php if($beCat): ?><span>/</span><span><?= htmlspecialchars($beCat); ?></span><?php endif; ?></nav>
 <header class="be-page-heading"><div><span class="be-eyebrow"><?= $beCopy('shop_eyebrow'); ?></span><h1><?= !empty($search)?'A little discovery.':($beCat?htmlspecialchars($beCat):$beCopy('shop_heading')); ?></h1><p><?= !empty($search)?'Results for “'.htmlspecialchars($search).'”':$beCopy('shop_intro'); ?></p></div><span class="be-page-count"><?= number_format($total ?? 0); ?><small><?= $beCopy('shop_count_label'); ?></small></span></header>
 <form class="be-collection-search" action="<?= $beRoot.'/products'; ?>" method="get"><label class="be-sr-only" for="be-catalogue-search">Search products</label><span aria-hidden="true">⌕</span><input id="be-catalogue-search" name="search" type="search" value="<?= htmlspecialchars($search ?? ''); ?>" placeholder="<?= $beCopy('shop_search'); ?>"><?php if(!empty($category_id)): ?><input type="hidden" name="category" value="<?= (int)$category_id; ?>"><?php endif; ?><button type="submit">Search <span aria-hidden="true">↗</span></button></form>
 <div class="be-shop-layout">
 <aside class="be-shop-sidebar"><details class="be-collection-filter" open><summary><?= $beCopy('shop_filters'); ?> <span aria-hidden="true">+</span></summary><nav aria-label="Product categories"><a class="<?= empty($category_id)?'is-current':''; ?>" <?= empty($category_id)?'aria-current="page"':''; ?> href="<?= htmlspecialchars($beUrl(['category'=>0])); ?>"><?= $beCopy('shop_all'); ?> <span>↗</span></a><?php foreach(($categories ?? []) as $c): ?><a class="<?= (int)($category_id ?? 0)===(int)$c->id?'is-current':''; ?>" href="<?= htmlspecialchars($beUrl(['category'=>(int)$c->id])); ?>"><?= htmlspecialchars($c->category_name); ?></a><?php endforeach; ?></nav></details><div class="be-shopping-help"><span class="be-eyebrow"><?= $beCopy('shop_help_eyebrow'); ?></span><p><?= $beCopy('shop_help_heading'); ?></p><a href="<?= $beRoot.(!empty($site_content['contact_enabled'])?'/contact':'#be-connect'); ?>"><?= $beCopy('shop_help_cta'); ?> ↗</a></div></aside>
 <div class="be-shop-results"><div class="be-results-bar"><span><?= empty($total)?'No items found':number_format(($page-1)*$limit+1).'–'.number_format(min($total,$page*$limit)).' of '.number_format($total).' '.htmlspecialchars($beValue('item_label')); ?></span><?php if(!empty($search)||!empty($category_id)): ?><a href="<?= $beRoot.'/products'; ?>">Clear filters ×</a><?php else: ?><span><?= $beCopy('shop_results_note'); ?></span><?php endif; ?></div>
 <?php if(!empty($products)): ?><?php $this->load->view('themes/botanical_elegance/_catalogue_grid',['beItems'=>$products]); ?><?php else: ?><section class="be-empty-state"><span aria-hidden="true">✳</span><h2><?= $beCopy('shop_empty_heading'); ?></h2><p><?= $beCopy('shop_empty_text'); ?></p><a class="be-pill" href="<?= $beRoot.'/products'; ?>"><?= $beCopy('shop_explore'); ?> ↗</a></section><?php endif; ?>
 <?php if(($total_pages ?? 0)>1): ?><nav class="be-pagination" aria-label="Product pages"><?php if($page>1): ?><a href="<?= htmlspecialchars($beUrl(['page'=>$page-1])); ?>" aria-label="Previous page">←</a><?php endif; ?><?php for($i=max(1,$page-2);$i<=min($total_pages,$page+2);$i++): ?><a href="<?= htmlspecialchars($beUrl(['page'=>$i])); ?>" <?= $i===$page?'aria-current="page"':''; ?>><?= $i; ?></a><?php endfor; ?><?php if($page<$total_pages): ?><a href="<?= htmlspecialchars($beUrl(['page'=>$page+1])); ?>" aria-label="Next page">→</a><?php endif; ?></nav><?php endif; ?>
 </div></div>
</main>
